/** Derive client and monochrome tray artwork from the approved application icon. */
import { writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

const packageRoot = dirname(dirname(fileURLToPath(import.meta.url)))
const source = join(packageRoot, 'build', 'app-icon.png')
const client = await sharp(source).resize(128, 128).toColourspace('srgb').png().toBuffer()
await writeFile(join(packageRoot, 'src/client/robo-app-icon.ts'),
  '/** Generated by scripts/generate-robo-brand-assets.mjs; do not edit. */\n'
  + `export const ROBO_APP_ICON_DATA_URL = 'data:image/png;base64,${client.toString('base64')}'\n`)

const wordmarkSource = join(packageRoot, 'build', 'brand', 'robocoding-wordmark-image2.png')
const wordmark = await sharp(wordmarkSource)
  .trim({ background: { r: 0, g: 0, b: 0, alpha: 0 } })
  .resize({ width: 512 })
  .png()
  .toBuffer()
await writeFile(join(packageRoot, 'src/client/robo-brand-wordmark.ts'),
  '/** Generated from the approved Image 2 wordmark; do not edit. */\n'
  + `export const ROBO_BRAND_WORDMARK_DATA_URL = 'data:image/png;base64,${wordmark.toString('base64')}'\n`)

// Extract the bright robot from its dark tile, retaining a crisp silhouette at tray sizes.
const silhouette = await sharp(source).flatten({ background: '#000000' })
  .resize(256, 256).greyscale().threshold(128).png().toBuffer()
const svg = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 50 50">\n'
  + '<defs><mask id="robot" x="0" y="0" width="50" height="50" maskUnits="userSpaceOnUse" mask-type="luminance">'
  + `<image width="50" height="50" xlink:href="data:image/png;base64,${silhouette.toString('base64')}"/>`
  + '</mask></defs>\n<rect width="50" height="50" fill="#4D6BFE" mask="url(#robot)"/>\n</svg>\n'
await writeFile(join(packageRoot, 'build/tray-icon.svg'), svg)
